/* ---- Guided design cases. In every step the FIRST option is correct; it is shuffled when shown. ---- */
var CASES=[
{id:"shortener",title:"URL shortener",blurb:"Turn long links into short ones and redirect fast. A classic read-heavy design.",
 reqs:[["100M","new links a month"],["100:1","reads to writes"],["<100 ms","redirect"],["5 years","retention"]],
 steps:[
  {t:"Pin down the scope",q:"Before drawing boxes, what do you settle first?",
   o:["Read and write volume, link lifetime, custom aliases, and the latency target","Which database vendor to buy","How many microservices to create","The color of the landing page"],
   why:"Requirements decide every later choice. Volume sizes the system, lifetime sizes storage, and the latency target decides whether a cache is needed.",adds:"Read-heavy (100:1), 7-character codes, redirect under 100 ms, links kept 5 years."},
  {t:"Estimate the load",q:"100 million new links a month with 100 times as many reads. About how many redirects per second on average?",
   o:["About 4,000 per second","About 40 per second","About 400,000 per second","About 40 million per second"],
   why:"100M a month is about 40 writes per second (100M / 2.5M seconds). Times 100 reads gives about 4,000 per second. Plan for 3 to 5 times that at peak, and note that 5 years of links is around 6 billion rows, a few terabytes.",adds:"Load: about 40 writes/s and 4,000 reads/s average, 15-20K reads/s at peak. Storage: about 3 TB over 5 years."},
  {t:"Generate short codes",q:"How should each new short code be produced?",
   o:["Base62-encode a unique ID from a counter or ID service","Take the first 7 characters of an MD5 hash and hope it is unique","Use the long URL itself as the code","Pick a random 3-character string"],
   why:"A unique ID can never collide. Seven base62 characters give 62^7, about 3.5 trillion codes. Truncated hashes collide and need extra checks, and 3 characters give only about 238,000 codes.",adds:"Codes: base62 of a unique ID, 7 characters, about 3.5 trillion possible."},
  {t:"Choose storage",q:"Which store fits the main table that maps a short code to a long URL?",
   o:["A key-value store or sharded SQL table keyed by short code","A full-text search engine","A graph database","One in-memory map on a single server"],
   why:"Every lookup is by exact key and rows are small. A key-value or sharded relational store handles billions of such rows. A single in-memory map loses data on restart and cannot hold the volume.",adds:"Storage: sharded key-value or SQL table, short code as the key, replicated."},
  {t:"Make redirects fast",q:"Redirects dominate traffic. What most reduces latency and database load?",
   o:["Cache hot short codes in memory in front of the database","Add more indexes to the write path","Buy a larger database server and nothing else","Compress the redirect response"],
   why:"A small share of links gets most of the clicks. An in-memory cache such as Redis answers those in well under a millisecond. Evict with LRU so the hot set stays resident.",adds:"Cache: hot codes in Redis with LRU eviction in front of the database."},
  {t:"Pick the redirect status",q:"The business wants accurate click analytics. Which redirect should the server send?",
   o:["302 Found, so browsers ask the server on every click","301 Moved Permanently, because it is the fastest","200 OK with the URL in the body","204 No Content"],
   why:"A 301 can be cached by browsers, which then skip your server, so you lose clicks. A 302 keeps every click visible. If analytics do not matter, 301 saves load.",adds:"Redirect: 302 so every click reaches the service. Clicks recorded through a queue."},
  {t:"Survive failures",q:"The primary database fails. What keeps most redirects working?",
   o:["Cache plus read replicas keep serving reads while a replica is promoted","Nothing, so show an error page","Restart every API server","Switch to HTTP"],
   why:"Most redirects are reads. Replicas and the cache can serve them during a failover, and only creating new links needs the primary for a short time.",adds:"Resilience: read replicas, automatic failover, stateless API servers behind a load balancer."}
 ],
 summary:[["Entry","A load balancer in front of several stateless API servers."],["Read path","Cache first, then read replicas of a sharded store."],["Write path","An ID service gives a unique code, which is written to the primary."],["Analytics","Clicks go to a queue and workers aggregate them off the hot path."]],
 tradeoffs:["302 keeps analytics accurate, 301 reduces load. Choose by what the business needs.","Counter IDs are simple and unique but guessable. Random IDs hide order but need collision checks.","A bigger cache lifts hit rate and costs memory. Hot links make a small cache enough."]},

{id:"feed",title:"News feed",blurb:"Show each user a fast, ranked feed of posts from people they follow.",
 reqs:[["50M","daily users"],["200K/s","feed reads"],["5K/s","new posts"],["<300 ms","feed load"]],
 steps:[
  {t:"Find what shapes the design",q:"Which fact shapes the design the most?",
   o:["Reads far outnumber writes, and users expect the feed in under 300 ms","The maximum length of a post","The font used in the app","The number of emoji supported"],
   why:"With 200K reads against 5K writes per second, the feed must be cheap to read. That points to doing work at write time.",adds:"Read-heavy, 40:1. Feed must load in under 300 ms."},
  {t:"Build the feed ahead of time",q:"For most users, when should a feed be assembled?",
   o:["On write: push each new post into every follower's feed","On read: query every followed account and merge results each time","Only once a day in a batch","Never, let the client fetch each friend separately"],
   why:"Fan-out on write does extra work once per post so that each read is a single lookup. Fan-out on read makes every request expensive, which is the wrong side to burden at 200K per second.",adds:"Fan-out on write: workers add the post id to each follower's feed."},
  {t:"Handle very popular accounts",q:"An account with 40 million followers posts. What should you do?",
   o:["Skip fan-out for it and merge its recent posts into feeds at read time","Fan out to all 40 million feeds immediately","Forbid it from posting","Delay every other user's posts"],
   why:"One post would cause 40 million writes. A hybrid approach pushes for normal accounts and pulls for celebrities, merging at read time.",adds:"Hybrid: celebrities are pulled at read time and merged with the pushed feed."},
  {t:"Store precomputed feeds",q:"Where should the ready-made feed for each user live?",
   o:["In an in-memory store such as Redis, as a list of post ids","In a relational table scanned for every request","In object storage as one file per user","Only in the user's browser"],
   why:"A list of recent post ids per user is small and read constantly. Memory gives sub-millisecond lookups. The full posts are fetched by id from the post store or its cache.",adds:"Feed cache: per-user list of the latest few hundred post ids in Redis."},
  {t:"Deliver media",q:"How should photos and videos reach the user?",
   o:["Keep them in object storage and serve them through a CDN","Send them through the API servers","Store them in the feed cache","Embed them in the database rows"],
   why:"Media is large and static. A CDN serves it from an edge near the user and keeps that traffic off your application servers.",adds:"Media: object storage behind a CDN. Posts hold only links."},
  {t:"Page through the feed",q:"How should the client request older posts?",
   o:["With a cursor such as the last seen post id","With page numbers and OFFSET","By downloading the entire feed once","By refreshing randomly"],
   why:"New posts constantly shift page boundaries. With page numbers a user sees repeats or gaps. A cursor always continues exactly after what was seen.",adds:"Pagination: cursor-based, using the last seen post id."},
  {t:"Recover from a cold cache",q:"The feed cache restarts empty. What should happen?",
   o:["Rebuild each feed lazily on first read from the follow graph and post store, with limits","Show errors until an engineer reloads it","Rebuild every feed for all users at once","Delete all posts"],
   why:"Lazy rebuild spreads the work over time. Rate limits and request coalescing stop a burst of rebuilds from overloading the database.",adds:"Recovery: lazy rebuild with request coalescing and rate limits."}
 ],
 summary:[["Write path","Post is saved, then a queue and workers fan it out to followers' cached feeds."],["Read path","API reads the feed list from Redis, loads posts by id, merges celebrity posts, ranks, and returns a cursor."],["Data","Post store, follow graph store, feed cache, object storage for media."],["Edge","CDN for images and video."]],
 tradeoffs:["Fan-out on write spends storage and write work to make reads fast.","The hybrid design adds complexity to handle accounts with huge follower counts.","Cached feeds can be slightly stale. That is usually fine for a feed."]},

{id:"chat",title:"Chat app",blurb:"Deliver messages in real time to people who may be online or offline.",
 reqs:[["100M","users"],["20M","online at once"],["500K/s","messages"],["<200 ms","delivery"]],
 steps:[
  {t:"Choose a connection style",q:"How do messages reach online users in real time?",
   o:["Persistent WebSocket connections to gateway servers","The client polls every second","Email each message","Reload the page"],
   why:"A persistent connection lets the server push a message the moment it arrives. Polling at this scale creates enormous idle traffic and adds delay.",adds:"Gateways: WebSocket connections, balanced across many servers."},
  {t:"Route to the recipient",q:"How does the system find which gateway holds the recipient's connection?",
   o:["A session store mapping each user to a gateway","Broadcast every message to all gateways","Ask gateways one by one until one answers","Guess by user name"],
   why:"A fast key-value store such as Redis records which gateway each user is on. The sender's gateway looks it up and forwards directly.",adds:"Session store: user id to gateway, updated on connect and disconnect."},
  {t:"Handle offline users",q:"The recipient is offline. What should happen?",
   o:["Store the message, send a push notification, and deliver on reconnect","Drop the message","Retry the socket for an hour","Ask the sender to resend later"],
   why:"The store makes delivery durable. The push notification wakes the device, and the app syncs from the last message it has when it reconnects.",adds:"Offline path: durable store plus push notification service."},
  {t:"Keep messages in order",q:"How do you keep messages in order inside one conversation?",
   o:["Assign increasing sequence numbers per conversation in one place","Trust each client's clock","Use random message ids","Sort alphabetically"],
   why:"Client clocks drift and disagree. A per-conversation counter gives one authoritative order, and clients detect gaps by missing numbers.",adds:"Ordering: per-conversation sequence numbers."},
  {t:"Store the history",q:"Which storage fits 500K messages per second?",
   o:["A key-value or wide-column store partitioned by conversation id and ordered by sequence","One SQL table with a global lock","Plain files on a single server","Only the client device"],
   why:"Partitioning by conversation keeps one chat's messages together, so loading history is a single range read, and writes spread across many nodes.",adds:"Message store: partitioned by conversation id, sorted by sequence."},
  {t:"Never lose a message",q:"A server crashes during delivery. How do you avoid losing or duplicating the message?",
   o:["Persist before acknowledging, and retry with a message id that receivers de-duplicate","Acknowledge first and store later","Never retry","Delete messages after sending"],
   why:"Writing first means a crash cannot lose an acknowledged message. Retries can repeat a message, so a unique id lets the receiver ignore duplicates.",adds:"Reliability: write-ahead persistence, retries, idempotent delivery by message id."},
  {t:"Support large groups",q:"A group has 1,000 members. How should a message be handled?",
   o:["Store it once and fan out delivery to each member's gateway","Store a full copy for every member","Disallow large groups","Send it by email"],
   why:"One stored copy saves space, and members read it by id. Delivery work still fans out, but storage does not multiply.",adds:"Groups: one stored message, fan-out of delivery by membership list."}
 ],
 summary:[["Connection","Clients hold WebSockets to gateways behind a load balancer."],["Routing","Session store finds the recipient's gateway."],["Storage","Partitioned message store with sequence numbers."],["Offline","Push notifications and sync on reconnect."]],
 tradeoffs:["Persisting before acknowledging adds a few milliseconds and prevents loss.","Keeping connection state in gateways makes deployments harder, so drain connections gradually.","Stronger ordering needs a single owner per conversation, which limits parallelism inside one chat."]},

{id:"video",title:"Video streaming",blurb:"Accept uploads of any size and play them smoothly on any network.",
 reqs:[["10M","daily viewers"],["500 hours","uploaded a minute"],["<2 s","start time"],["30 Tbps","peak delivery"]],
 steps:[
  {t:"Accept big uploads",q:"How should large video files reach storage?",
   o:["The client uploads in chunks directly to object storage with a pre-signed URL","Through API server memory in one request","By email","Into a relational database column"],
   why:"Direct chunked uploads keep gigabytes off your API servers, and a broken upload can resume from the last chunk.",adds:"Upload: chunked, direct to object storage, resumable."},
  {t:"Convert to many formats",q:"How should the video be converted into several resolutions?",
   o:["Put a job on a queue and run a fleet of transcoding workers in parallel","Convert inside the upload request","Ask viewers' phones to convert it","Skip conversion"],
   why:"Transcoding takes minutes of CPU. A queue absorbs bursts, and workers can split a video into segments and process them in parallel.",adds:"Processing: queue plus transcoder workers, segment-level parallelism."},
  {t:"Choose a streaming format",q:"How should the player receive the video?",
   o:["Adaptive bitrate: short segments at several quality levels, chosen by the player","One large MP4 for everyone","A live camera feed","Full download before playing"],
   why:"The player measures bandwidth and switches between qualities every few seconds. That avoids buffering on weak networks and uses full quality on strong ones.",adds:"Format: HLS or DASH segments at multiple bitrates."},
  {t:"Deliver at huge scale",q:"How do you deliver 30 Tbps?",
   o:["Serve segments from a CDN with edge servers near viewers","From one data center","Through the API servers","By peer-to-peer only"],
   why:"No single site can send that much. CDN edges hold popular segments close to viewers and fetch from the origin only on a miss.",adds:"Delivery: CDN edges, origin in object storage."},
  {t:"Count views",q:"Millions of views arrive each minute. How do you count them?",
   o:["Buffer events in a stream and aggregate in batches","Update one database row on every view, synchronously","Count only at midnight by hand","Ask the user to report views"],
   why:"A single hot row would be a bottleneck. Streaming and batching turns millions of tiny writes into a few updates.",adds:"View counts: event stream with batch aggregation."},
  {t:"Control cost",q:"Most old videos are rarely watched. What is a sensible storage plan?",
   o:["Keep popular segments on the edge, serve the long tail from origin, and move cold files to cheaper storage","Keep every video on every edge forever","Delete anything over a month old","Store everything in memory"],
   why:"Watch patterns are very uneven. Tiering matches cost to demand while keeping popular content fast.",adds:"Cost: tiered storage and cache-on-demand at the edge."}
 ],
 summary:[["Upload","Pre-signed chunked upload to object storage."],["Process","Queue and workers create bitrates and segments."],["Play","CDN serves adaptive bitrate segments."],["Metadata","Database plus cache for titles, owners and counts."]],
 tradeoffs:["More renditions improve quality of experience and cost more storage and compute.","Longer segments are cheaper to serve and slower to adapt to network changes.","A larger CDN footprint lowers latency and raises cost."]}

,
{id:"rides",title:"Ride sharing",blurb:"Match riders with nearby drivers in about a second, with moving locations everywhere.",
 reqs:[["5M","drivers online"],["250K/s","location updates"],["<1 s","match time"],["99.99%","availability"]],
 steps:[
  {t:"Ingest locations",q:"Drivers report their position every few seconds. How should the system ingest 250K updates per second?",
   o:["Send them to a location service that overwrites each driver's latest position in memory","Insert every update into a SQL table and keep it forever","Write each update to a text file","Ask riders to report driver positions"],
   why:"Only the latest position matters for matching. Overwriting a small in-memory record is cheap. Keeping history can go to a separate stream for analytics.",adds:"Location service: latest position per driver in memory, history to a stream."},
  {t:"Find nearby drivers",q:"How do you find available drivers near a rider quickly?",
   o:["A geospatial index such as a geohash grid or quadtree","Scan all 5 million drivers each time","Sort drivers by name","Ask each driver in turn"],
   why:"A geohash maps coordinates to cells. Look up the rider's cell and its neighbours and you only look at a handful of drivers.",adds:"Geo index: geohash cells to driver lists, updated as drivers move."},
  {t:"Choose how to offer trips",q:"A rider requests a car. How should offers go out?",
   o:["Rank nearby drivers by pickup time and offer to one at a time with a short timeout","Broadcast to every driver in the city","Offer to a random driver and never retry","Let drivers bid"],
   why:"One offer at a time avoids many drivers racing for one trip. A short timeout moves quickly to the next best driver.",adds:"Matching: ranked candidates, sequential offers with timeouts."},
  {t:"Avoid double booking",q:"Two riders could be matched to the same driver at the same moment. How do you prevent it?",
   o:["Claim the driver with an atomic compare-and-set on the driver's state","Hope it does not happen","Tell drivers to ignore the second one","Lock the entire city"],
   why:"An atomic claim lets exactly one request move the driver from available to reserved. The other sees the change fail and tries the next driver.",adds:"Consistency: atomic claim of driver state before confirming a trip."},
  {t:"Show the car on the map",q:"How does the rider see the driver's position moving?",
   o:["The server pushes position updates over a persistent connection every few seconds","The rider's app refreshes the whole database","The driver phones the rider","Positions are shown only at the end"],
   why:"Pushing small updates uses far less bandwidth than polling, and it keeps the map smooth.",adds:"Tracking: server push of positions to the rider app."},
  {t:"Scale across cities",q:"How should the location and matching data be split as you grow?",
   o:["Partition by region or city, since trips rarely cross them","One global index for the whole planet","Split by driver name","Split by rider age"],
   why:"Matching is local. Regional partitions keep indexes small and also limit the impact of a failure to one region.",adds:"Partitioning: regional shards of the geo index and matching service."}
 ],
 summary:[["Locations","Drivers stream positions to a location service and a regional geo index."],["Matching","Matching service queries the index, ranks, and claims a driver atomically."],["Trips","Durable trip database with a state machine from requested to completed."],["Updates","Push channel for live positions and offers."]],
 tradeoffs:["Frequent updates give accurate matches and cost battery and bandwidth.","Smaller geohash cells give precision and need more cell lookups.","Regional partitions simplify scaling but complicate trips that cross a border."]},

{id:"files",title:"File sync",blurb:"Keep files identical across a user's devices, like a cloud drive.",
 reqs:[["50M","users"],["10 GB","largest file"],["<5 s","sync of a small edit"],["11 nines","durability"]],
 steps:[
  {t:"Move large files",q:"A user edits one page in a 2 GB file. How do you avoid uploading everything again?",
   o:["Split files into chunks, hash each one, and upload only changed chunks","Re-upload the whole file every time","Ask the user to save a copy","Compress to one byte"],
   why:"Chunking makes updates proportional to what changed. A resumable chunk upload also survives network drops.",adds:"Chunking: about 4 MB blocks, each identified by its hash."},
  {t:"Save space",q:"Thousands of users store the same file. What reduces storage?",
   o:["Deduplicate by content hash so identical chunks are stored once","Store a separate copy per user","Delete duplicates by hand","Ban shared files"],
   why:"A chunk's hash is its identity. If it already exists the upload is skipped and metadata just points to it.",adds:"Deduplication: content-addressed block store."},
  {t:"Separate data from metadata",q:"How should the system be organized?",
   o:["A metadata database for the file tree and versions, and a block store for content","Everything in one large file","Metadata inside each block","Only in the client"],
   why:"The metadata is small and needs transactions. Blocks are large and need cheap, durable storage. Each can scale independently.",adds:"Metadata DB (tree, versions, block lists) plus object storage for blocks."},
  {t:"Notify other devices",q:"How does a second device learn that a file changed?",
   o:["It holds a long-lived connection and receives a change notification, then fetches the diff","It downloads the whole file list every second","The user refreshes manually","It guesses"],
   why:"Notifications deliver updates within seconds with almost no idle cost, and the diff keeps transfers small.",adds:"Sync: notification channel plus incremental change feed."},
  {t:"Resolve conflicts",q:"Two devices edit the same file offline. What should happen?",
   o:["Keep both versions and create a conflicted copy for the user to resolve","Silently keep the later timestamp and discard the other","Delete both","Block editing"],
   why:"Silently discarding work is the worst outcome. Keeping both is safe and puts the user in control.",adds:"Conflicts: version history, conflicted copy on divergence."},
  {t:"Protect the data",q:"Which approach meets very high durability?",
   o:["Replicate blocks across several zones and verify checksums regularly","Store on one disk with a backup yearly","Keep one copy in memory","Rely on user backups"],
   why:"Independent copies in separate failure domains, plus background integrity checks and repair, make loss extremely unlikely.",adds:"Durability: multi-zone replication or erasure coding with scrubbing."}
 ],
 summary:[["Client","Watches files, chunks, hashes, uploads missing blocks."],["Service","Metadata database and block store, with notification fan-out."],["Sync","Change feed per device and conflict copies."],["Storage","Replicated, content-addressed blocks."]],
 tradeoffs:["Smaller chunks save bandwidth on edits and add metadata overhead.","Deduplication across users saves space and raises privacy questions for encrypted data.","Keeping version history costs storage and protects against mistakes."]},

{id:"limiter",title:"Rate limiter",blurb:"Cap requests per key across many servers without slowing normal traffic.",
 reqs:[["10M","API keys"],["100K/s","checks"],["<5 ms","added delay"],["99.99%","availability"]],
 steps:[
  {t:"Choose an algorithm",q:"Which algorithm lets short bursts through while holding a steady average?",
   o:["Token bucket","Fixed window counter, with no smoothing","Sorting requests alphabetically","Random rejection"],
   why:"A token bucket refills at a steady rate and each request spends a token, so a quiet client can burst. It needs only a token count and a timestamp per key.",adds:"Algorithm: token bucket per key."},
  {t:"Place the check",q:"Where should the limit be enforced?",
   o:["At the API gateway, before requests reach backend services","Inside every service differently","In the user's browser","In the database"],
   why:"Rejecting early saves backend work and gives one consistent rule. Client-side checks can be bypassed.",adds:"Placement: gateway middleware."},
  {t:"Share the counters",q:"There are many gateway servers. Where do counters live?",
   o:["In a shared in-memory store such as Redis","In each server's local memory","In log files","In the client"],
   why:"With local counters a client could send its full limit to each server. A shared store keeps one count per key.",adds:"State: counters in Redis, keyed by API key."},
  {t:"Avoid races",q:"Two servers check the same key at the same instant. How do you stay correct?",
   o:["Do the read-modify-write atomically, for example with a Lua script","Read, then write in two steps","Use sleep","Retry until it works"],
   why:"A two-step update can let both requests see the last token. Doing it inside the store as one operation removes the gap.",adds:"Atomicity: single Redis script per check."},
  {t:"Plan for store failure",q:"The counter store is unreachable. What should the limiter do?",
   o:["Fall back to a coarse local limit and alert, choosing fail open or closed on purpose","Crash every request","Ignore the problem silently","Delete all keys"],
   why:"Failing open keeps the product up and risks abuse. Failing closed protects backends and risks an outage. A local fallback bounds the damage either way.",adds:"Failure mode: local fallback limit, replicated Redis, alerts."},
  {t:"Tell the client",q:"What should a rejected client receive?",
   o:["429 Too Many Requests with a Retry-After header","200 OK with an empty body","500 Internal Server Error","A redirect to the home page"],
   why:"429 tells clients they are the cause, and Retry-After tells them when to come back. Well-behaved clients then back off.",adds:"Response: 429 with Retry-After and rate limit headers."}
 ],
 summary:[["Check","Gateway calls the limiter, which runs an atomic token bucket in Redis."],["Rules","Limits come from a config store per plan and endpoint."],["Failure","Replicated store, local fallback, alerts on rejections."],["Feedback","429 with Retry-After."]],
 tradeoffs:["Token bucket allows bursts. Sliding window is stricter and uses more memory.","Fail open favors availability. Fail closed favors protection.","A central store is accurate and adds a network hop. Local counters are fast and approximate."]},

{id:"notify",title:"Notification system",blurb:"Send push, SMS and email reliably, on time, without spamming anyone.",
 reqs:[["10M","users"],["1B","per day at peak"],["<5 s","for one-time codes"],["0","duplicates wanted"]],
 steps:[
  {t:"Decouple producers",q:"How should other services request a notification?",
   o:["Publish an event to a queue that the notification service consumes","Call each provider directly from every service","Share a spreadsheet","Email the notification team"],
   why:"A queue absorbs bursts and lets producers move on. The notification service can retry independently without slowing the caller.",adds:"Ingest: events published to a durable queue."},
  {t:"Separate the channels",q:"Push, SMS and email have different providers and limits. How do you structure workers?",
   o:["Separate workers per channel behind a router","One worker that does everything","A single thread","Only email"],
   why:"Each channel fails and scales differently. Separate workers isolate a slow provider so it does not block the others.",adds:"Workers: one pool per channel, with provider adapters."},
  {t:"Protect urgent messages",q:"A marketing blast must not delay login codes. What do you do?",
   o:["Use separate priority queues with reserved capacity for urgent messages","Send everything in arrival order","Send codes last","Pause marketing forever"],
   why:"With one queue, a huge campaign would put login codes behind millions of messages. Priority lanes keep latency predictable.",adds:"Priority: separate queues and consumers for urgent and bulk."},
  {t:"Prevent duplicates",q:"A worker crashes after sending but before acknowledging. How do you avoid sending twice?",
   o:["Give each notification an id and check it before sending, so retries are idempotent","Never retry","Send twice to be safe","Ask the user to ignore repeats"],
   why:"Queues redeliver. Recording sent ids, ideally with a unique constraint, makes a repeat harmless.",adds:"Idempotency: unique notification id with a sent-record."},
  {t:"Retry sensibly",q:"The SMS provider is failing. What is the best retry plan?",
   o:["Retry with exponential backoff and jitter, then move to a dead-letter queue","Retry instantly in a tight loop","Drop the message","Retry forever without limit"],
   why:"Backoff avoids overloading a struggling provider, and a dead-letter queue keeps failures for inspection and replay.",adds:"Retries: backoff with jitter and a dead-letter queue."},
  {t:"Respect users",q:"How do you avoid annoying people?",
   o:["Check preferences and apply per-user rate limits and quiet hours before sending","Send every possible notification","Let users guess","Ignore opt-outs"],
   why:"Users who feel spammed turn notifications off entirely. A preferences check and per-user throttles protect trust and legal compliance.",adds:"Preferences: opt-outs, quiet hours and per-user throttles."}
 ],
 summary:[["Intake","Events go to priority queues."],["Delivery","Channel workers call providers with idempotent sends."],["Reliability","Backoff, dead-letter queue, provider failover."],["Control","Preferences and rate limits before sending."]],
 tradeoffs:["Exactly-once delivery is not achievable end to end, so aim for at-least-once with idempotency.","Provider failover improves reliability and adds cost and complexity.","Batching saves money and delays messages."]}
];

/* ===== Unit 11: Services and patterns ===== */
;UNITS.push(unit("Services and patterns","Splitting a system into services, and the patterns that connect them.","boxes",[
 lesson("Monolith or microservices","Choosing how to split a system",[
  mc("What is a monolith?",["One deployable application containing all the features","Many small services","A kind of database","A load balancer"],"A well-structured monolith is simple to build, test and deploy, and is a good starting point."),
  mc("What is the main benefit of microservices?",["Teams can build, deploy and scale parts independently","They are always faster","They need less code","They remove the need for a network"],"The benefit is organisational and operational independence, and it comes with a cost in complexity."),
  mc("Which is a real cost of microservices?",["Network calls, partial failure, distributed data and harder debugging","Cheaper hosting","Fewer deployments","Simpler transactions"],"What was a function call becomes a network call that can fail or be slow."),
  mc("A five-person startup is building a first product. What is usually the best starting point?",["A modular monolith","Fifty microservices","One service per developer","A mesh of functions"],"Split later, along boundaries you have actually learned from running the system."),
  mc("How should service boundaries be chosen?",["Around business capabilities, so each service owns its data and changes for one reason","By technical layer, such as one service for all databases","By the team's favourite language","Randomly"],"Domain-driven design calls these bounded contexts."),
  mc("Two services read and write the same database tables directly. What is wrong?",["They are tightly coupled through the schema, so neither can change freely","Nothing, it is efficient","The database is too small","It makes tests faster"],"Each service should own its data and expose it through an API or events."),
  mc("What is a distributed monolith?",["Services that must be deployed together because they are tightly coupled","A very large database","A CDN","A well-designed system"],"You get the costs of microservices and none of the independence."),
  mc("Which signal suggests extracting a service from a monolith?",["One part needs very different scaling, or a team keeps blocking others","The code is old","You want to use a new language","A tool is trendy"],"Extract for a concrete reason: scale, team autonomy, or isolation of risk."),
  mc("What is the strangler fig approach?",["Gradually route features to new services until the old system can be retired","Rewrite everything at once","Delete the monolith","Duplicate the database"],"It reduces the risk of a big-bang rewrite."),
  mc("Service A needs data owned by service B on every request. What are the options?",["Call B's API, cache it, or keep a local copy updated by events","Read B's database directly","Merge all data into one table","Ignore the need"],"Each has a freshness and coupling trade-off. Direct database access is the option to avoid."),
  order("Order a sensible path as a product grows.",["Start with a modular monolith","Find clear boundaries and pain points","Extract the first service behind an API","Repeat as needed, one service at a time"],"Evolve by evidence, not by guess."),
  match("Match each term to its meaning.",[["Bounded context","A boundary within which a model has one meaning"],["Modular monolith","One deployable with strong internal boundaries"],["Strangler fig","Incremental replacement of a system"],["Distributed monolith","Microservices that cannot deploy independently"]],"Architecture should fit the organisation and the stage of the product.")
 ]),
 lesson("Gateways, discovery and meshes","How services find and call each other",[
  mc("What does an API gateway do?",["Gives clients one entry point and handles routing, authentication and rate limiting","Stores data","Compiles code","Replaces the database"],"It keeps cross-cutting concerns out of every service."),
  mc("What is a backend for frontend (BFF)?",["A gateway tailored to one kind of client, such as mobile","A type of database","A cache","A load balancer"],"Each client gets exactly the data shape it needs, with fewer round trips."),
  mc("Why do services need service discovery?",["Instances come and go, so addresses change","To encrypt traffic","To store logs","To compress data"],"A registry or DNS-based system tells callers which instances are healthy and where."),
  mc("What is client-side load balancing?",["The caller picks an instance from the discovered list","The server picks the caller","A DNS trick only","A CDN feature"],"It avoids a central load balancer in the path but puts logic in every client."),
  mc("What is a service mesh?",["A layer of sidecar proxies that handles service-to-service networking such as retries, mTLS and metrics","A type of database","A message queue","A gateway for end users"],"It moves networking concerns out of application code."),
  mc("What is a downside of a service mesh?",["Operational complexity and extra latency per hop","It cannot do encryption","It removes observability","It forbids microservices"],"Adopt it when you have enough services to justify it."),
  mc("A service retries failed calls at every layer of a five-layer chain. What risk does this create?",["A retry storm that multiplies load on a struggling dependency","Faster responses","Lower cost","Nothing"],"Retry at one layer, with backoff and jitter, and respect a retry budget."),
  mc("Why add jitter to exponential backoff?",["So that many clients do not retry at exactly the same moment","To make it faster","To use more memory","To avoid TLS"],"Random spread prevents synchronised waves of traffic."),
  mc("When should a call be synchronous (request-response) rather than asynchronous (events)?",["When the caller needs the answer to continue","When the work can wait","When the work is huge","Never"],"Use asynchronous messaging to decouple when an immediate answer is not required."),
  mc("What is a sidecar?",["A helper process deployed alongside a service instance","A kind of database","A backup server","A CDN edge"],"Common sidecars handle proxying, logging or secrets."),
  order("Order a request through a typical microservice setup.",["Client calls the API gateway","Gateway authenticates and routes the request","Service discovers and calls a downstream service","Response flows back to the client"],"Each hop adds latency and a place to fail, so keep call chains shallow."),
  match("Match each component to its job.",[["API gateway","Single entry point for clients"],["Service registry","Know where instances are"],["Service mesh","Manage service-to-service traffic"],["Circuit breaker","Stop calling a failing dependency"]],"These pieces are the plumbing of a microservice system.")
 ]),
 lesson("CQRS and event sourcing","Separating reads from writes, and storing events",[
  mc("What is CQRS?",["Using separate models for commands (writes) and queries (reads)","A database engine","A type of cache","A load balancing method"],"Each side can be shaped and scaled for its own job."),
  mc("Why use CQRS?",["Read and write needs differ greatly, such as complex writes and many simple fast reads","It is always simpler","It removes the need for databases","It prevents bugs"],"A read model can be denormalised and cached for speed."),
  mc("What is the downside of CQRS with separate stores?",["The read model is eventually consistent with the write model","Reads are impossible","Writes are slow","It needs no events"],"Design the user experience for a short delay."),
  mc("What does event sourcing store?",["The sequence of events that happened, not just the current state","Only the latest state","Only logs","Only snapshots"],"Current state is derived by replaying events."),
  mc("What is a benefit of event sourcing?",["A complete audit trail and the ability to rebuild state or new views","Smaller storage","No schema","No need for backups"],"You can add a new read model later by replaying history."),
  mc("What is a challenge of event sourcing?",["Evolving event schemas and long replays","No history","Slow writes only","No consistency at all"],"Snapshots shorten replays, and versioned events handle change."),
  mc("How are read models in CQRS kept up to date?",["Handlers consume events and update the read store","By hand","By email","They are not"],"This is a projection of events into a query-friendly shape."),
  mc("A bank account is modelled as events: Deposited 100, Withdrew 30. What is the balance?",["70","130","100","30"],"Replaying events gives the state. This is why ledgers are a natural fit."),
  mc("Where does the saga pattern fit with events?",["It coordinates multi-service workflows through events and compensations","It replaces events","It is a database","It stores passwords"],"Services react to events and publish new ones to move a workflow forward."),
  mc("When is event sourcing a poor choice?",["Simple CRUD applications with no need for history","Financial ledgers","Audit-heavy systems","Systems needing replay"],"It adds real complexity, so adopt it only when you need what it gives."),
  order("Order the flow of CQRS with an event-driven read model.",["Client sends a command","Write model validates and stores the change and emits an event","A projection updates the read model","Queries are served from the read model"],"There is a delay between steps 2 and 3, and the UI should tolerate it."),
  match("Match each term to its meaning.",[["Command","Request to change state"],["Event","Fact that something happened"],["Projection","Read model built from events"],["Snapshot","Saved state to shorten replay"]],"These patterns are tools, not defaults.")
 ])
]));
add("11-1",[
 tc("The monolith is not the enemy","A monolith is one deployable unit. It is easy to run, test, debug and change early on, because everything is in one process and one transaction can touch all the data. Many successful systems stayed monolithic for years.\n\nThe pain appears with scale of the team and codebase: builds get slow, deployments risky, and parts with different needs cannot scale separately.",["Simple to start with.","Pain grows with team and code size.","A modular monolith is a strong default."],"Do not pay the cost of distribution before you need it."),
 tc("What microservices give and cost","Microservices split a system into small services, each owned by a team, with its own data and deployment. Benefits: independent releases, independent scaling, fault isolation, and technology freedom.\n\nCosts: every call is now a network call that can fail or be slow; data is spread across services so joins and transactions become hard; testing, debugging and operating many services is more work. You need strong automation and observability first.",["Independent deploy and scale.","Network and data complexity.","Needs automation and observability."],"Microservices solve people and scaling problems by creating distributed-systems problems."),
 tc("Drawing the boundaries","Draw service boundaries around business capabilities, such as orders, payments and catalogue, rather than technical layers. Each service should own its data, expose an API or events, and change for a single reason. If two services always change together or share a database, the boundary is wrong.\n\nDomain-driven design calls such a cohesive area a bounded context.",["Split by business capability.","Each service owns its data.","Services that always change together should merge."],"Boundaries are hard to move later, so learn the domain first."),
 tc("Migrating safely","Use the strangler fig pattern: put a facade in front of the monolith, build a new service for one capability, route that traffic to it, and repeat until the monolith is gone or small. Move data ownership deliberately, using events or dual writes with verification.\n\nExtract for a reason such as scaling, team autonomy or risk isolation, never just for fashion.",["Incremental, not big-bang.","Facade routes traffic.","Move data ownership carefully."],"Every extraction should have a measurable payoff.")
]);
add("11-2",[
 tc("The front door","An API gateway is the single entry point for clients. It routes requests to services and handles shared concerns such as authentication, rate limiting, TLS termination, caching and request logging. A backend for frontend (BFF) is a gateway shaped for one client type, such as mobile, that combines several service calls into one response.\n\nKeep business logic out of the gateway, or it turns into a new monolith.",["One entry point.","Shared concerns in one place.","BFF per client type.","No business logic."],"A gateway simplifies clients and centralises the edge."),
 tc("Finding services","Instances start, stop and move, so callers cannot hard-code addresses. Service discovery keeps a registry of healthy instances, either through DNS, a registry such as Consul or etcd, or the platform itself, such as Kubernetes Services. Callers or a load balancer pick an instance from the list.\n\nHealth checks keep unhealthy instances out of the list.",["Addresses change constantly.","Registry or platform DNS.","Health checks keep the list honest."],"Discovery turns names into currently healthy addresses."),
 tc("Service mesh","A service mesh adds a proxy next to each service instance (a sidecar). The proxies handle retries, timeouts, load balancing, mutual TLS and metrics, controlled centrally. Application code stays focused on business logic.\n\nThe cost is extra moving parts, resource use and a small amount of latency per hop. It pays off when you have many services and need uniform security and observability.",["Sidecar proxies.","Retries, mTLS, metrics in one place.","Extra complexity and latency."],"Adopt a mesh when you have the problem it solves."),
 tc("Calling safely","Every network call can fail, so wrap it: a timeout, a bounded number of retries with exponential backoff and jitter, a circuit breaker, and a fallback. Retry only idempotent operations, or use idempotency keys. Retry at one layer only, or retries multiply across layers into a storm.\n\nPrefer asynchronous events when the caller does not need an immediate answer, since it decouples availability.",["Timeout, retry with jitter, breaker.","Idempotent or keyed retries.","Retry at one layer.","Async when possible."],"Design every remote call as if it will fail.")
]);
add("11-3",[
 tc("CQRS: split the models","In CQRS, commands change state through one model, and queries read through another. Reads and writes often have very different needs: writes need validation and consistency, while reads want fast, denormalised data shaped for the screen. Separating them lets each be optimised and scaled alone.\n\nIt can be as simple as two code paths over one database, or as separate stores fed by events.",["Commands write, queries read.","Optimise each side separately.","Can start simple."],"Use CQRS where read and write shapes truly differ."),
 tc("Event sourcing","Instead of storing the current state, event sourcing stores every change as an immutable event: AccountOpened, MoneyDeposited, MoneyWithdrawn. The current state is computed by replaying events, and snapshots speed that up.\n\nYou get a perfect audit log, the ability to answer 'what did it look like last Tuesday?', and the freedom to build new read models from history. It pairs naturally with CQRS.",["Store events, not state.","Replay to rebuild.","Audit trail and time travel.","Pairs with CQRS."],"Events are facts, and facts do not change."),
 tc("Projections and eventual consistency","A projection consumes the event stream and maintains a read model, such as a search index, a cache or a table shaped for one screen. Because the update is asynchronous, the read model lags slightly behind the writes. The user interface needs to handle that, for example by showing the new item straight away from the command response.\n\nProjections can be rebuilt from scratch by replaying events.",["Handlers build read models.","Small lag is normal.","Rebuild by replay."],"Design for the gap between write and visible read."),
 tc("When not to use them","CQRS and event sourcing add real complexity: more components, event versioning, replays, and harder debugging. A simple CRUD service with a relational database is far easier. Reach for these patterns when there is a clear need such as auditability, complex domains, or very different read and write loads.\n\nSagas, outboxes and idempotent consumers are the supporting patterns that make event-driven systems reliable.",["Simple CRUD does not need them.","Complexity is the cost.","Supported by outbox, sagas and idempotency."],"A pattern is justified by the problem it removes.")
]);

/* ===== Unit 12: Interview playbook ===== */
;UNITS.push(unit("Interview playbook","A repeatable method for any design problem, in an interview or at work.","flag",[
 lesson("The framework","Structure beats inspiration",[
  mc("What should you do first in a system design interview?",["Clarify requirements and scope","Draw the database","Pick a technology","Start coding"],"Open questions are expected. The problem is intentionally vague."),
  mc("Which is a non-functional requirement?",["The system should respond in under 200 ms at the 99th percentile","Users can post a message","Users can follow others","Users can upload photos"],"Non-functional requirements describe qualities such as latency, availability, scale and consistency."),
  mc("Why do back-of-the-envelope estimates matter?",["They show whether you need sharding, caching or a CDN","They impress by being exact","They replace design","They are required by law"],"Rough numbers tell you which problems are real. Only the order of magnitude matters."),
  mc("Roughly how many seconds are in a day?",["About 100,000 (86,400)","About 1,000","About 1 million","About 10 million"],"Use 10^5 for quick maths: 100 million requests a day is about 1,000 per second."),
  mc("What is a sensible order for a design?",["Requirements, estimates, API, data model, high-level design, deep dives, bottlenecks","Deep dive first, requirements last","Database, UI, requirements","Only a diagram"],"Starting broad and then going deep shows structure and keeps you on track."),
  mc("What does 'read-heavy' tell you about the design?",["Caches, replicas and CDNs will matter","Writes need sharding first","You need no database","Queues are essential"],"The shape of the traffic directs your choices."),
  mc("The interviewer asks 'what if this component fails?'. What are they checking?",["That you consider failure, redundancy and recovery","That you know its brand","That you can type","That you finish early"],"Show a single point of failure and how you remove it."),
  mc("What is a good habit when you choose between two options?",["State the trade-off and why you pick one for these requirements","Pick the most popular","Never decide","Pick the newest"],"There is no best technology, only best for the constraints."),
  mc("You have 45 minutes. Roughly how should you spend them?",["Spend about a third on requirements and high-level design, and the rest on depth","All on requirements","All on one deep dive","All on drawing"],"Leave time to go deep on one or two interesting parts, usually the hardest."),
  mc("What is the benefit of designing the API early?",["It pins down what the system actually does and drives the data model","It is decorative","It chooses the database","It is not needed"],"Think in terms of a handful of endpoints, with the key inputs and outputs."),
  order("Order the steps of the framework.",["Clarify requirements and scope","Estimate scale","Define the API and data model","Sketch the high-level design","Deep dive and discuss bottlenecks and trade-offs"],"Revisit earlier steps if a requirement changes."),
  match("Match each step to what you produce.",[["Requirements","Functional and non-functional lists"],["Estimation","QPS, storage and bandwidth"],["High-level design","Components and data flow"],["Deep dive","Detailed solution to the hard part"]],"A framework lets you stay calm and cover the ground.")
 ]),
 lesson("Mapping problems to building blocks","Recognise the pattern",[
  mc("Users read a hot, rarely changing product page millions of times a day. Which block comes first?",["CDN and cache","A bigger database","Sharding writes","A queue"],"The cheapest read is the one that never reaches your servers."),
  mc("Many clients send events that must be processed reliably but not instantly. What fits?",["A message queue with workers","Synchronous calls","A cache","A CDN"],"Queues absorb bursts and decouple producers from consumers."),
  mc("You need to find nearby drivers in real time. Which idea helps?",["A geospatial index such as geohash or S2 cells","A full-text index","A bigger CDN","A cron job"],"Index by location cell, query the neighbouring cells and filter by distance."),
  mc("A feed must show posts from people you follow. Which trade-off is central?",["Fan-out on write versus fan-out on read","SQL versus a hash","TCP versus UDP","Light versus dark mode"],"Precomputing feeds is fast to read but costly for accounts with many followers. A hybrid approach is common."),
  mc("You must stop a user from sending too many requests. What do you use?",["A rate limiter such as a token bucket","A CDN","A search index","A saga"],"Keep counters in a fast shared store, keyed by user or IP."),
  mc("A service must tell whether a username is taken among billions. What can cut database lookups?",["A Bloom filter in front of the database","A bigger index","A CDN","A queue"],"If the filter says 'not present', you can skip the lookup."),
  mc("You must keep two systems in step without distributed transactions. What pattern applies?",["Outbox plus events with idempotent consumers","Two-phase commit everywhere","Manual copying","Shared database"],"Reliable events give eventual consistency without cross-system locks."),
  mc("Large file uploads and downloads. What is the usual design?",["Object storage with presigned URLs and a CDN","Store files in the main database","Stream through app servers","Email"],"Keep large bytes off your application servers."),
  mc("Users need autocomplete suggestions within tens of milliseconds. What fits?",["A trie or prefix index, cached, with precomputed top results","A full table scan","A message queue","A saga"],"Precompute popular completions for each prefix and serve from memory."),
  mc("You need an ordered, durable stream of events that several consumers read at their own pace. What fits?",["A partitioned log such as Kafka","A cache","A DNS record","A CDN"],"Consumers track their own offsets, and events can be replayed."),
  order("Order a design path for a notification system.",["Accept the request through an API","Put it on a queue","Workers deliver through email, push or SMS providers","Track status, retries and delivery receipts"],"Queues give buffering, retries and the ability to scale workers."),
  match("Match each problem to its core pattern.",[["Hot read traffic","Cache and CDN"],["Traffic spikes","Queue and autoscaling"],["Nearby search","Spatial index"],["Abuse protection","Rate limiting"]],"Most designs are familiar blocks arranged to fit new constraints.")
 ]),
 lesson("Trade-offs and common mistakes","Sounding like an engineer, not a catalogue",[
  mc("Which answer shows strong judgement?",["'I would use X because our reads dominate, at the cost of Y.'","'Use microservices, always.'","'It depends.' and nothing more","'Whatever you prefer.'"],"State the reason and the cost. That is the skill being tested."),
  mc("What is a common mistake at the start?",["Jumping into a diagram without clarifying requirements","Asking questions","Estimating scale","Stating assumptions"],"Without requirements you may design the wrong system."),
  mc("What is over-engineering?",["Adding sharding, microservices and queues the numbers do not justify","Using a database","Writing tests","Drawing a diagram"],"Start simple, show where it breaks, then scale the part that needs it."),
  mc("The interviewer challenges your choice. What is the best response?",["Discuss the trade-offs openly, and change your mind if the argument is good","Defend it at any cost","Say nothing","Pick the opposite instantly"],"They want to see how you reason and collaborate."),
  mc("Which statement about single points of failure is right?",["Identify them and add redundancy or a failover","They do not matter","Only databases have them","They are only theoretical"],"Check the load balancer, the database, the queue and the coordination service."),
  mc("What do you do when you do not know a detail?",["Say what you do know, state an assumption, and carry on","Pretend","Stop","Change the subject"],"Honest reasoning is better than a confident wrong answer."),
  mc("What is a data-driven way to justify caching?",["Show the read to write ratio and the hit rate you expect","Say caching is good","Say it is popular","Say it is cheap"],"Numbers make a choice defensible."),
  mc("Why mention monitoring and failure handling in a design?",["Production readiness is part of design","It fills time","It is optional trivia","It replaces scaling"],"Mention metrics, alerts, retries, backups and graceful degradation."),
  mc("A candidate designs only the happy path. What is missing?",["Failures, retries, edge cases and consistency","Colours","Names","Branding"],"Ask yourself what happens when each arrow in the diagram fails."),
  mc("What is the best use of the last few minutes?",["Summarise the design, its limits and what you would improve next","Add random components","Stay silent","Rewrite the requirements"],"A concise wrap-up shows ownership and perspective."),
  order("Order a good response to a challenge on your design.",["Listen to the concern fully","Restate it to check you understood","Weigh the trade-off against the requirements","Defend or adjust the design, explaining why"],"Collaborative reasoning is the signal."),
  match("Match each mistake to its fix.",[["Skipping requirements","Ask clarifying questions first"],["Over-engineering","Start simple and justify each addition"],["Ignoring failure","Walk each component and ask what if it fails"],["No trade-offs","State the cost of every choice"]],"Most interview failures are failures of process, not knowledge.")
 ])
]));
add("12-1",[
 tc("Start by narrowing the problem","A design prompt such as 'design a news feed' is deliberately open. Ask who the users are, what the core features are and which to skip, how many users and how much traffic, what matters most (latency, availability, consistency), and any constraints. Write the agreed scope down where both of you can see it.\n\nFunctional requirements say what the system does. Non-functional requirements say how well it must do it.",["Ask about users and features.","Separate functional from non-functional.","Write the scope down."],"Five minutes of questions prevents forty minutes of wrong design."),
 tc("Estimate the scale","Do rough numbers: daily active users, actions per user, requests per second (divide by about 100,000 seconds a day), peak as 2-3 times average, storage per item times items, and bandwidth. The aim is to see whether one machine could do it, whether data fits on one disk, and what the read to write ratio is.\n\nUse round numbers, show your working, and move on.",["Daily users to QPS.","Peak is a multiple of average.","Storage and bandwidth.","Read to write ratio."],"Estimates tell you which components you really need."),
 tc("API, data model, then boxes","Define a few key endpoints with their inputs and outputs. Sketch the main entities and relationships, and choose a store for each. Then draw the high-level flow of a request: client, edge, services, data stores, async parts.\n\nGet an end-to-end design on the board early, even a simple one. Then improve it.",["Key endpoints first.","Entities and storage choice.","End-to-end flow early."],"A working simple design beats a perfect partial one."),
 tc("Deep dive and wrap-up","Choose one or two parts that are hardest or most interesting, such as feed fan-out, hot keys, or consistency of a counter, and go deep with alternatives and trade-offs. Then cover bottlenecks and failure: what is the first thing to break at ten times the load, and what is a single point of failure.\n\nFinish with a short summary and what you would do next.",["Deep dive on the hard parts.","Bottlenecks and failures.","Summarise and name next steps."],"Depth on the right part shows seniority.")
]);
add("12-2",[
 tc("Problems repeat","New problems rarely need new ideas. Most are a small set of building blocks arranged differently: caching and CDNs for read-heavy loads, queues for spikes and slow work, partitioning for data size, replication for availability, rate limiting for protection, search indexes for text, spatial indexes for location, object storage for files, streams for events.\n\nLearning to recognise which blocks a problem asks for is the main skill.",["A small toolbox covers most cases.","Match symptoms to blocks.","Recognition is the skill."],"When you read a prompt, name the blocks it hints at."),
 tc("Read the load shape","Ask whether the system is read-heavy or write-heavy, spiky or steady, latency-sensitive or batch, and how fresh the data must be. A read-heavy, tolerant-of-staleness system points to caching and replicas. A write-heavy one points to partitioning, append-only storage and queues. Spiky work points to queues and autoscaling.\n\nThe workload shape picks the architecture.",["Read or write heavy.","Spiky or steady.","Latency or throughput.","How stale is acceptable."],"State the load shape out loud and design for it."),
 tc("Classic problems and their pivot","URL shortener: unique id generation and a read-heavy cache. News feed: fan-out on write or read. Chat: persistent connections and ordered delivery. Video streaming: object storage, transcoding pipeline and CDN. Ride sharing: geospatial indexing and matching. Rate limiter: counters in a shared fast store. Notification service: queues and provider retries. File sync: chunking, deduplication and change feeds.\n\nEach has one central difficulty; find it and spend your time there.",["Each classic has a pivot.","Find the central difficulty.","Spend time where it is hard."],"The pivot is usually a trade-off, such as latency against cost."),
 tc("Combining blocks","A real design layers blocks: the edge (CDN, load balancer, gateway), stateless services that scale horizontally, caches in front of data stores, queues for work that can wait, a primary store with replicas or shards, and specialised stores for search, files and analytics. Observability and security wrap the lot.\n\nIf you can explain why each box is there, and what breaks without it, you understand the design.",["Layered architecture.","Stateless services scale out.","Cache, queue, store.","Observe and secure everything."],"Every box on the diagram should have a reason.")
]);
add("12-3",[
 tc("Trade-offs are the content","Every choice gains something and costs something: caching gains speed and costs freshness; sharding gains scale and costs simple queries; async gains resilience and costs immediacy; microservices gain team autonomy and cost operational complexity. Say both halves aloud.\n\nA useful phrase is: 'Given requirement X, I choose A over B, accepting the cost of Y.'",["Gains and costs.","Tie choices to requirements.","Say the cost out loud."],"If you cannot name the downside, you do not understand the choice."),
 tc("Common mistakes","Skipping requirements. Naming technologies without reasons. Over-engineering for scale the numbers do not support. Ignoring failure modes and single points of failure. Hiding uncertainty rather than stating assumptions. Talking without drawing, or drawing without explaining. Getting defensive when challenged.\n\nMost of these are habits of process, which means you can fix them with practice.",["Process failures dominate.","State assumptions.","Draw and narrate.","Welcome challenges."],"Practice the framework until it feels automatic."),
 tc("Failure thinking","For each component ask: what happens if it is slow, down, or wrong? Then add the standard answers: timeouts and retries with backoff, redundancy and failover, circuit breakers, graceful degradation, idempotent operations, backups and restore tests, and monitoring with alerts.\n\nMention one or two unprompted. It signals production experience.",["Slow, down, wrong.","Standard defences.","Raise them unprompted."],"Designing the failure path is half of the design."),
 tc("How to keep learning","Re-do the cases in this app from memory. Take any product you use and sketch how it might work. Read engineering blogs and papers on real systems: Dynamo, Bigtable, Kafka, Raft, Spanner. Practice with a friend, speaking aloud and timing yourself.\n\nThe goal is not memorised answers but a fluent toolbox and the habit of reasoning from requirements.",["Redo cases from memory.","Sketch products you use.","Read real system write-ups.","Practise aloud."],"Fluency comes from repeated, deliberate practice.")
]);

/* ---- Mock interviews ---- */
var INTERVIEWS=[
  {id:"whatsapp",title:"Design WhatsApp",
   facts:[["1B","messages a day"],["99.99%","availability"],["<200 ms","send time"],["20:00","time limit"]],
   stages:[
    {t:"Clarify the requirements",q:"List the functional and non-functional requirements you would confirm before drawing anything.",
     pts:["Functional: one-to-one chat, groups, delivery and read receipts, media, offline delivery","Non-functional: send latency under 200 ms, 99.99% availability, no lost messages","Scope: what is left out, such as voice calls and status updates"]},
    {t:"Estimate traffic and storage",q:"There are 1 billion messages a day. Estimate messages per second and daily storage.",
     pts:["1 billion divided by 86,400 is about 12K messages per second on average, and peaks are 3 to 5 times that","At about 100 bytes of text per message, that is roughly 100 GB of text per day","Media dominates storage, so keep it in object storage and send a link in the message"]},
    {t:"Sketch the architecture",q:"Draw the high-level design from the sender's phone to the recipient's phone.",
     pts:["Persistent connections such as WebSockets to a fleet of chat gateway servers","A session service that records which gateway holds each user's connection","A message store, plus a queue and push notification for users who are offline"]},
    {t:"Delivery and ordering",q:"How do messages arrive in order and without duplicates from the user's point of view?",
     pts:["Per-conversation sequence numbers let the client order messages and spot gaps","Acknowledge at each hop and retry, using unique message ids so retries are idempotent","The client drops duplicates by message id"]},
    {t:"Failures and trade-offs",q:"A gateway server crashes. What happens, and what trade-offs did you make?",
     pts:["Clients reconnect to another gateway and resume from the last acknowledged sequence number","Messages are written to storage before they are acknowledged, so a crash loses nothing","Trade-off: durable writes cost throughput, so shard storage by conversation id"]}
   ]},
  {id:"limiter",title:"Design a rate limiter",
   facts:[["10M","active API keys"],["100/min","default limit"],["<5 ms","added delay"],["20:00","time limit"]],
   stages:[
    {t:"Clarify the requirements",q:"What would you confirm about who is limited, how, and what the caller sees?",
     pts:["Who is limited: per user, per API key, per IP, or per endpoint","Hard or soft limit, and the response: a 429 status with a Retry-After header","Whether it spans many servers, and whether it fails open or closed if the limiter is down"]},
    {t:"Estimate load and memory",q:"There are 10 million keys, each with a counter. Estimate memory and request rate.",
     pts:["A counter and timestamp is about 50 to 100 bytes, so 10 million keys is around 1 GB, which fits in memory","If the API sees 100K requests per second, the limiter sees the same number of checks","Each check must be one fast in-memory operation, around a millisecond"]},
    {t:"Choose an algorithm",q:"Choose between fixed window, sliding window and token bucket, and explain your pick.",
     pts:["Token bucket allows short bursts and needs very little memory per key","Fixed window is simple but can let through double the limit at a window edge","Sliding window log is exact but costs more memory per key"]},
    {t:"Place it in the architecture",q:"Where does the limiter run, and where is its state kept?",
     pts:["In the API gateway or middleware, before requests reach the services","Shared counters in a store such as Redis so every server sees the same count","Atomic updates, such as a Lua script or INCR with expiry, to avoid race conditions"]},
    {t:"Failures and trade-offs",q:"The counter store becomes unavailable. What do you do?",
     pts:["Choose fail open for availability or fail closed for protection, and say why","Fall back to a coarse local limit on each server so abuse stays bounded","Replicate the store, and alert on a spike in 429 responses"]}
   ]},
  {id:"shortener",title:"Design a URL shortener",
   facts:[["100M","new URLs a month"],["100:1","read to write"],["<100 ms","redirect time"],["20:00","time limit"]],
   stages:[
    {t:"Clarify the requirements",q:"What would you confirm before designing?",
     pts:["Functional: create a short link, redirect, optional custom alias and expiry","Non-functional: very low redirect latency, high availability, links must not collide","Out of scope for now: analytics detail and user accounts"]},
    {t:"Estimate traffic and storage",q:"100 million new URLs a month with a 100:1 read to write ratio. Estimate QPS and storage over 5 years.",
     pts:["100M a month is about 40 writes per second, so about 4,000 redirects per second on average","6 billion URLs over 5 years at about 500 bytes each is about 3 TB, which is small","Reads dominate, so caching is the main lever"]},
    {t:"Generate short codes",q:"How do you generate unique 7-character codes?",
     pts:["Base62 gives 62^7, about 3.5 trillion codes, which is plenty","Encode a unique counter or Snowflake-style id, or hand out ranges of ids to each server","Hashing the URL needs collision handling, so counters are simpler"]},
    {t:"Redirect path and caching",q:"Describe how a redirect is served quickly.",
     pts:["Check a cache such as Redis first, since a small share of links get most traffic","On a miss, read from a key-value store and fill the cache","Use 301 for permanent links or 302 if you need every click to reach you for analytics"]},
    {t:"Failures and trade-offs",q:"What breaks at 10 times the load, and what did you trade off?",
     pts:["Replicate the store and shard by short code so no single node is a bottleneck","Rate limit creation to stop abuse, and scan targets for malicious links","Trade-off: 302 gives analytics but costs more load than a cached 301"]}
   ]},
  {id:"feed",title:"Design a news feed",
   facts:[["300M","daily users"],["200","average follows"],["<500 ms","feed load"],["20:00","time limit"]],
   stages:[
    {t:"Clarify the requirements",q:"What do you confirm about the feed?",
     pts:["Functional: post, follow, see a feed of followed accounts in time or ranked order","Non-functional: fast loads, high availability, eventual consistency is fine","Scope: text and image links, with media handled by object storage and a CDN"]},
    {t:"Estimate load",q:"300 million daily users open the feed 5 times a day. Estimate feed reads and writes.",
     pts:["1.5 billion feed reads a day is about 17K per second, with peaks of several times that","Posts are far fewer, perhaps 100 million a day, so the system is read-heavy","Each post is small, and media bytes are served from a CDN"]},
    {t:"Fan-out strategy",q:"Compare fan-out on write and fan-out on read, and pick one.",
     pts:["Fan-out on write precomputes each follower's feed, so reads are a quick lookup but writes multiply","Fan-out on read assembles the feed at request time, which is cheap to write and slow to read","A hybrid is common: push for normal users, pull for celebrities with millions of followers"]},
    {t:"Storage and ranking",q:"Where is each feed stored, and how is it ranked?",
     pts:["Keep a list of post ids per user in a cache such as Redis, and hydrate post details on read","Store posts in a sharded database keyed by post id or user id","Rank by recency first, then add scoring signals as a separate service"]},
    {t:"Failures and trade-offs",q:"What happens when a celebrity posts, and what did you trade off?",
     pts:["Do not fan out to millions of followers. Pull their posts at read time and merge","Fan-out runs through a queue so spikes are absorbed and retried","Trade-off: precomputed feeds can be slightly stale, which is acceptable for this product"]}
   ]},
  {id:"video",title:"Design video streaming",
   facts:[["50M","daily viewers"],["500 hrs","uploaded per minute"],["<2 s","start time"],["20:00","time limit"]],
   stages:[
    {t:"Clarify the requirements",q:"What do you confirm first?",
     pts:["Functional: upload, process, watch, search, resume playback","Non-functional: fast start, smooth playback on varying networks, high durability","Out of scope: recommendations, comments and ads"]},
    {t:"Estimate storage and bandwidth",q:"500 hours of video are uploaded every minute. Estimate daily storage and egress.",
     pts:["That is 720,000 hours a day, and at about 1 GB per hour per rendition it is hundreds of terabytes a day","Egress is far larger than ingest, because every view is a download","Bandwidth cost drives the design, so a CDN is essential"]},
    {t:"Upload and processing pipeline",q:"What happens between an upload and the video being watchable?",
     pts:["Upload directly to object storage with presigned URLs, in chunks that can resume","A queue triggers workers that transcode into several resolutions and bitrates","Store the metadata in a database, and mark the video ready when processing is done"]},
    {t:"Delivery",q:"How is video delivered smoothly to different devices?",
     pts:["Adaptive bitrate streaming, such as HLS or DASH, splits video into short segments at several qualities","The player switches quality based on the network speed","A CDN caches popular segments close to viewers, with origin storage as the fallback"]},
    {t:"Failures and trade-offs",q:"What are the bottlenecks and trade-offs?",
     pts:["Transcoding is expensive, so scale workers with the queue and retry failed segments","Cache popular content at the edge and long-tail content from the origin","Trade-off: more renditions improve quality but cost storage and processing"]}
   ]},
  {id:"rides",title:"Design ride sharing",
   facts:[["1M","active drivers"],["5s","location update interval"],["<1 s","match latency"],["20:00","time limit"]],
   stages:[
    {t:"Clarify the requirements",q:"What do you confirm?",
     pts:["Functional: request a ride, match with a nearby driver, track the trip, pay","Non-functional: low match latency, real-time location, high availability in a city","Out of scope: pricing details, driver onboarding and ratings"]},
    {t:"Estimate location traffic",q:"1 million drivers send a location every 5 seconds. Estimate the write rate.",
     pts:["1 million divided by 5 is about 200,000 location writes per second","Only the latest position matters, so it can live in memory with no history required for matching","Keep history in a separate pipeline for analytics"]},
    {t:"Find nearby drivers",q:"How do you find the closest available drivers quickly?",
     pts:["Divide the map into cells using geohash, S2 or H3, and index drivers by cell","Query the rider's cell and the neighbouring cells, then rank by distance or ETA","Keep the index in memory, partitioned by region"]},
    {t:"Matching and the trip lifecycle",q:"How do you match and avoid assigning one driver to two riders?",
     pts:["Offer the ride to one driver at a time, or a few, with a short timeout","Use an atomic state change, such as a compare-and-set on the driver's status, to claim a driver","Model the trip as a state machine: requested, matched, picked up, completed, paid"]},
    {t:"Failures and trade-offs",q:"What fails, and what did you trade off?",
     pts:["If a regional service fails, route to another instance with the state rebuilt from fresh driver updates","Use idempotent payments and a saga for charging and receipts","Trade-off: more frequent location updates improve accuracy but cost battery and bandwidth"]}
   ]}
];

UNITS.forEach(function(u,ui){u.lessons.forEach(function(l,li){l.id=(ui+1)+"-"+(li+1);l.ui=ui;l.li=li;});});
var FLAT=[];UNITS.forEach(function(u){u.lessons.forEach(function(l){FLAT.push(l);});});
PEND.forEach(function(p){
  var l=null;FLAT.forEach(function(x){if(x.id===p[0])l=x;});
  if(!l)throw new Error("add(): no lesson "+p[0]);
  if(p[1])l.teach=p[1];
  if(p[2])l.ex=l.ex.concat(p[2]);
});

